// lib-ssh-correlate (N8N-4.2), pure: can this alert's source address be
// correlated, and the one bounded TheHive query that finds its related alerts:
// alerts with an `ip` observable equal to data.srcip, dated (TheHive `date` =
// the Wazuh timestamp) within ssh_correlation.window_s of this alert's event
// time in both directions (edges included), carrying one of prefilter_tags,
// excluding the alert itself; at most query_limit. TheHive 5.7 has no
// caseTemplate query attribute, so the exact template check is done on the
// answer ("Result"); the tag pre-filter only keeps the page for SSH alerts.
// Event time is the Wazuh timestamp, never n8n's clock.
function prepare(input) {
  const cfg = input?.config?.ssh_correlation;
  if (!cfg) return { action: 'invalid', message: 'lib-ssh-correlate needs the lib-config output (with ssh_correlation) as `config`' };
  const c = input.canonical;
  if (!c || typeof c !== 'object') return { action: 'invalid', message: 'lib-ssh-correlate needs the canonical alert as `canonical`' };
  const selfId = typeof input.thehive_alert_id === 'string' && input.thehive_alert_id !== '' ? input.thehive_alert_id : null;
  if (!selfId) return { action: 'invalid', message: 'lib-ssh-correlate needs the TheHive alert id as `thehive_alert_id`' };
  const skip = (reason, srcip = null) => ({ action: 'skip', reason, srcip });
  const srcip = typeof c.network?.srcip === 'string' ? c.network.srcip.trim() : '';
  if (srcip === '') return skip('no data.srcip');
  // The tags come from lib-extract-observables (agent, range:internal, ...):
  // one source of truth for what an address is.
  const obs = (Array.isArray(input.observables) ? input.observables : [])
    .find((o) => o && o.dataType === 'ip' && o.data === srcip);
  if (!obs) return skip(`data.srcip ${srcip} is not an ip observable of this alert`, srcip);
  const bad = cfg.skip_tags.filter((t) => Array.isArray(obs.tags) && obs.tags.includes(t));
  if (bad.length > 0) return skip(`address ${srcip} tagged ${bad.join(', ')}`, srcip);
  if (!Number.isFinite(c.date_ms)) return skip('no event time (timestamp)', srcip);
  const w = cfg.window_s * 1000;
  const fromMs = c.date_ms - w;
  const toMs = c.date_ms + w;
  const query = [
    { _name: 'listObservable' },
    { _name: 'filter', _and: [{ _field: 'dataType', _value: 'ip' }, { _field: 'data', _value: srcip }] },
    { _name: 'alert' },
    { _name: 'filter', _and: [
      { _gte: { _field: 'date', _value: fromMs } },
      { _lte: { _field: 'date', _value: toMs } },
      { _in: { _field: 'tags', _values: cfg.prefilter_tags } },
      { _not: { _field: '_id', _value: selfId } },
    ] },
    { _name: 'sort', _fields: [{ date: 'asc' }] },
    { _name: 'page', from: 0, to: cfg.query_limit },
  ];
  return { action: 'query', srcip, self_id: selfId, event_ms: c.date_ms, from_ms: fromMs, to_ms: toMs, body: { query } };
}

return [{ json: prepare($input.first().json) }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call is returned as `failed (thehive_unreachable)`: never parked.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.thehive_http;
const NODE = 'Find related TheHive alerts';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// lib-ssh-correlate (N8N-4.2): the query's answer -> related alerts and the
// escalation plan. Pure. Reached by exactly one path: skipped or invalid
// (no query), the answer, or the query failing for good. Never throws for a
// TheHive failure: `failed (<class>)`, and the plan keeps only this alert's
// campaign tag, so the playbook goes on and never parks for it.
//  - related: answer filtered again (defensive) on the case templates, the
//    window (|date - event time| <= window_s, both edges included) and self;
//    duplicates by _id removed; in date order. `listed`: the max_listed
//    nearest in time, in date order.
//  - a brute-force alert (any rule not in escalation_rule_ids) gets its own
//    campaign tag, plus the escalation of itself when a related alert carries
//    one of the escalation rules (40112): the earliest such alert is named.
//  - an escalation alert (40112) gets its campaign tag and escalates every
//    related alert of the brute-force template: tag, severity raised to
//    escalate_severity if lower (never lowered, D12), comment, metrics.
function ruleOf(tags) {
  const t = (Array.isArray(tags) ? tags : []).find((x) => typeof x === 'string' && x.startsWith('rule:'));
  return t ? t.slice(5) : null;
}

function classify(r) {
  if (r.decision === 'error') return r.retry_exhausted ? 'thehive_unreachable' : (r.http_status ? 'thehive_4xx' : 'thehive_error');
  if (r.statusCode !== 200) return r.statusCode >= 400 && r.statusCode < 500 ? 'thehive_4xx' : `http_${r.statusCode}`;
  if (!Array.isArray(r.body)) return 'bad_answer';
  return null;
}

function correlate(input, prep, answer) {
  const cfg = input.config.ssh_correlation;
  const c = input.canonical;
  const selfId = prep.self_id;
  const ruleId = c?.rule?.id ?? null;
  const role = cfg.escalation_rule_ids.includes(ruleId) ? 'login' : 'bruteforce';
  const base = { srcip: prep.srcip ?? null, window_s: cfg.window_s, event_ms: prep.event_ms ?? null, role, rule_id: ruleId };
  if (prep.action === 'invalid') return { ok: false, status: 'failed', class: 'invalid_input', message: prep.message, ...base, plan: null };
  if (prep.action === 'skip') return { ok: true, status: 'skipped', reason: prep.reason, ...base, plan: null };
  const campaignTag = `${cfg.tags.campaign_prefix}${prep.srcip}`;
  const selfTags = (Array.isArray(input.tags) ? input.tags : []).filter((t) => typeof t === 'string');
  const selfSeverity = Number.isInteger(input.severity) ? input.severity : null;
  const selfPlan = (escalation) => ({
    thehive_alert_id: selfId,
    wazuh_alert_id: c.wazuh_alert_id,
    source: input.source ?? null,
    rule_id: ruleId,
    add_tags: [campaignTag, ...(escalation ? [cfg.tags.escalated] : [])].filter((t) => !selfTags.includes(t)),
    severity_from: selfSeverity,
    severity_to: escalation && selfSeverity !== null && selfSeverity < cfg.escalate_severity ? cfg.escalate_severity : null,
    escalation,
  });
  const cls = classify(answer);
  if (cls) {
    return { ok: true, status: 'failed', class: cls, attempts: answer.attempts ?? null,
      message: answer.message ?? (answer.statusCode !== undefined ? `HTTP ${answer.statusCode}: ${JSON.stringify(answer.body)}`.slice(0, 500) : null),
      ...base, plan: { self: selfPlan(null), targets: [] } };
  }
  const w = cfg.window_s * 1000;
  const seen = new Set();
  const related = [];
  for (const a of answer.body) {
    if (!a || typeof a._id !== 'string' || a._id === selfId || seen.has(a._id)) continue;
    if (!cfg.templates.includes(a.caseTemplate)) continue;
    if (!Number.isFinite(a.date) || Math.abs(a.date - prep.event_ms) > w) continue;
    seen.add(a._id);
    const rid = ruleOf(a.tags);
    related.push({
      thehive_alert_id: a._id, wazuh_alert_id: a.sourceRef ?? null, rule_id: rid, case_template: a.caseTemplate,
      date_ms: a.date, date_iso: new Date(a.date).toISOString(), severity: a.severity ?? null, source: a.source ?? null,
      tags: Array.isArray(a.tags) ? a.tags : [],
      kind: cfg.escalation_rule_ids.includes(rid) ? 'login' : (a.caseTemplate === cfg.bruteforce_template ? 'bruteforce' : 'other'),
    });
  }
  related.sort((x, y) => x.date_ms - y.date_ms || (x.thehive_alert_id < y.thehive_alert_id ? -1 : 1));
  const listed = [...related]
    .sort((x, y) => Math.abs(x.date_ms - prep.event_ms) - Math.abs(y.date_ms - prep.event_ms) || x.date_ms - y.date_ms)
    .slice(0, cfg.max_listed)
    .sort((x, y) => x.date_ms - y.date_ms);
  const compact = ({ tags, ...r }) => r;
  let self;
  let targets = [];
  if (role === 'bruteforce') {
    const by = related.find((r) => r.kind === 'login') ?? null;
    self = selfPlan(by ? { by_wazuh_alert_id: by.wazuh_alert_id, by_thehive_alert_id: by.thehive_alert_id,
      by_rule_id: by.rule_id, by_date_ms: by.date_ms } : null);
  } else {
    self = selfPlan(null);
    targets = related.filter((r) => r.kind === 'bruteforce').map((r) => ({
      thehive_alert_id: r.thehive_alert_id, wazuh_alert_id: r.wazuh_alert_id, source: r.source, rule_id: r.rule_id,
      date_ms: r.date_ms,
      add_tags: r.tags.includes(cfg.tags.escalated) ? [] : [cfg.tags.escalated],
      severity_from: r.severity,
      severity_to: Number.isInteger(r.severity) && r.severity < cfg.escalate_severity ? cfg.escalate_severity : null,
      severity_final: Number.isInteger(r.severity) ? Math.max(r.severity, cfg.escalate_severity) : cfg.escalate_severity,
    }));
  }
  return { ok: true, status: 'done', attempts: answer.attempts ?? null, ...base,
    related_total: related.length, truncated: answer.body.length >= cfg.query_limit,
    related: related.map(compact), listed: listed.map(compact),
    plan: { self, targets } };
}

const input = $('Called by a workflow').first().json;
const prep = $('Prepare query').first().json;
return [{ json: correlate(input, prep, $input.first().json) }];
